// Regression baseline from beta2; compiled only by font-checks, never shipped in the product.
using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Drawing.Text;using System.IO;using System.Linq;using System.Runtime.InteropServices;
namespace ZiXing {
 public sealed class LegacyFontMatcher {
  [DllImport("gdi32.dll")]static extern IntPtr SelectObject(IntPtr hdc,IntPtr value);
  [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr value);
  [DllImport("gdi32.dll")]static extern uint GetFontData(IntPtr hdc,uint table,uint offset,byte[] data,uint size);
  [DllImport("gdi32.dll",CharSet=CharSet.Unicode)]static extern uint GetGlyphIndicesW(IntPtr hdc,string text,int length,ushort[] glyphs,uint flags);
  sealed class Face {public string Family;public FontStyle Style;}
  Dictionary<string,Face> catalog;
  static int U16(byte[] b,int n){return b[n]*256+b[n+1];}
  static string PostScript(IntPtr hdc){uint table=0x656d616e;uint count=GetFontData(hdc,table,0,null,0);if(count==0xffffffff||count>4*1024*1024||count<6)return null;byte[] b=new byte[count];if(GetFontData(hdc,table,0,b,count)==0xffffffff)return null;int n=U16(b,2),start=U16(b,4);string result=null;for(int i=0;i<n;i++){int p=6+12*i;if(p+12>b.Length)break;if(U16(b,p+6)!=6)continue;int size=U16(b,p+8),offset=start+U16(b,p+10),platform=U16(b,p);if(offset+size>b.Length)continue;string name=platform==0||platform==3?System.Text.Encoding.BigEndianUnicode.GetString(b,offset,size):System.Text.Encoding.ASCII.GetString(b,offset,size);if(platform==3)return name;result=name;}return result;}
  void EnsureCatalog(){if(catalog!=null)return;catalog=new Dictionary<string,Face>(StringComparer.Ordinal);using(var bitmap=new Bitmap(1,1))using(var g=Graphics.FromImage(bitmap))using(var collection=new InstalledFontCollection()){
   foreach(var family in collection.Families){foreach(var style in new[]{FontStyle.Regular,FontStyle.Bold,FontStyle.Italic,FontStyle.Bold|FontStyle.Italic}){if(!family.IsStyleAvailable(style))continue;try{using(var font=new Font(family,100,style,GraphicsUnit.Pixel)){IntPtr hfont=font.ToHfont(),hdc=g.GetHdc(),previous=IntPtr.Zero;try{previous=SelectObject(hdc,hfont);string name=PostScript(hdc);if(!string.IsNullOrEmpty(name)&&!catalog.ContainsKey(name))catalog[name]=new Face{Family=family.Name,Style=style};}finally{if(previous!=IntPtr.Zero)SelectObject(hdc,previous);g.ReleaseHdc(hdc);DeleteObject(hfont);}}}catch(ArgumentException){}}}
  }}
  static Mask Read(Bitmap source){using(var image=new Bitmap(source.Width,source.Height,PixelFormat.Format24bppRgb)){using(var g=Graphics.FromImage(image)){g.Clear(Color.White);g.DrawImageUnscaled(source,0,0);}var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format24bppRgb);try{var row=new byte[Math.Abs(data.Stride)];var pixels=new byte[image.Width*image.Height];for(int y=0;y<image.Height;y++){Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),row,0,row.Length);for(int x=0;x<image.Width;x++)pixels[y*image.Width+x]=(byte)((row[x*3]+row[x*3+1]+row[x*3+2])/3);}return new Mask(image.Width,image.Height,pixels);}finally{image.UnlockBits(data);}}}
  static string Png(Mask mask){using(var bitmap=new Bitmap(mask.Width,mask.Height,PixelFormat.Format24bppRgb)){var d=bitmap.LockBits(new Rectangle(0,0,mask.Width,mask.Height),ImageLockMode.WriteOnly,PixelFormat.Format24bppRgb);try{var row=new byte[Math.Abs(d.Stride)];for(int y=0;y<mask.Height;y++){for(int x=0;x<mask.Width;x++)row[x*3]=row[x*3+1]=row[x*3+2]=mask.Pixels[y*mask.Width+x];Marshal.Copy(row,0,IntPtr.Add(d.Scan0,y*d.Stride),row.Length);}}finally{bitmap.UnlockBits(d);}using(var memory=new MemoryStream()){bitmap.Save(memory,ImageFormat.Png);return Convert.ToBase64String(memory.ToArray());}}}
  Mask Render(Face face,string expected,string text,int width,int height){using(var font=new Font(face.Family,100,face.Style,GraphicsUnit.Pixel))using(var bitmap=new Bitmap(width,height,PixelFormat.Format24bppRgb))using(var g=Graphics.FromImage(bitmap))using(var family=new FontFamily(face.Family))using(var path=new GraphicsPath(FillMode.Winding)){
   IntPtr hfont=font.ToHfont(),hdc=g.GetHdc(),old=IntPtr.Zero;try{old=SelectObject(hdc,hfont);if(PostScript(hdc)!=expected)return null;var glyphs=new ushort[text.Length];if(GetGlyphIndicesW(hdc,text,text.Length,glyphs,1)==0xffffffff||glyphs.Any(x=>x==0xffff))return null;}finally{if(old!=IntPtr.Zero)SelectObject(hdc,old);g.ReleaseHdc(hdc);DeleteObject(hfont);}
   using(var format=(StringFormat)StringFormat.GenericTypographic.Clone()){format.FormatFlags|=StringFormatFlags.NoWrap;path.AddString(text,family,(int)face.Style,100,PointF.Empty,format);}var bounds=path.GetBounds();if(bounds.Width<=0||bounds.Height<=0)return null;using(var m=new Matrix(width/bounds.Width,0,0,height/bounds.Height,-bounds.X*width/bounds.Width,-bounds.Y*height/bounds.Height)){path.Transform(m);}g.Clear(Color.White);g.SmoothingMode=SmoothingMode.AntiAlias;g.FillPath(Brushes.Black,path);return Read(bitmap);
  }}
  public object Match(string imagePath,Dictionary<string,object> request,Action<object> progress){EnsureCatalog();var requested=Json.Array(request,"fonts").Cast<object>().Select(x=>x as string).Where(x=>!string.IsNullOrEmpty(x)).Distinct().ToArray();var lines=Json.Array(request,"lines");if(requested.Length>30000||lines.Length<1||lines.Length>20)throw new Exception("字体比较参数无效。");var resolved=requested.Where(catalog.ContainsKey).ToArray();var rows=new List<object>();using(var source=new Bitmap(imagePath)){if(source.Width>4500||source.Height>4500)throw new Exception("识别图片过大。");for(int index=0;index<lines.Length;index++){var line=(Dictionary<string,object>)lines[index];string text=Json.String(line,"text");if(string.IsNullOrWhiteSpace(text)||text.Length>120){rows.Add(new{index,candidates=new object[0],compared=0,original="",warning="单行最多 120 字，请分段匹配。"});continue;}
   double nx=Json.Number(line,"x"),ny=Json.Number(line,"y"),nw=Json.Number(line,"width"),nh=Json.Number(line,"height");if(nx<0||ny<0||nw<=0||nh<=0||nx+nw>1.0001||ny+nh>1.0001)throw new Exception("文字行坐标超出图片。");int x=Math.Max(0,(int)(nx*source.Width)),y=Math.Max(0,(int)((1-ny-nh)*source.Height)),r=Math.Min(source.Width,(int)Math.Ceiling((nx+nw)*source.Width)),b=Math.Min(source.Height,(int)Math.Ceiling((1-ny)*source.Height));if(r<=x||b<=y)throw new Exception("文字行坐标无效。");Mask crop;using(var region=source.Clone(new Rectangle(x,y,r-x,b-y),PixelFormat.Format24bppRgb))crop=Read(region);int[] tight=crop.Tight();if(tight==null){rows.Add(new{index,candidates=new object[0],compared=0,original="",warning="没有找到可比较的字形。"});continue;}int height=48,width=Math.Max(32,Math.Min(960,(int)(tight[2]*48.0/tight[3])));var target=crop.Normalize(tight,width,height);var best=new List<Tuple<string,double,Mask>>();int compared=0;
   for(int fi=0;fi<resolved.Length;fi++){var name=resolved[fi];Mask mask=null;try{mask=Render(catalog[name],name,text,width,height);}catch(ArgumentException){}catch(System.Runtime.InteropServices.ExternalException){}if(mask!=null){compared++;double score=Mask.Similarity(target,mask);if(best.Count<5||score>best[best.Count-1].Item2){best.Add(Tuple.Create(name,score,mask));best=best.OrderByDescending(v=>v.Item2).Take(5).ToList();}}if(fi%50==0)progress(new{type="progress",line=index+1,lines=lines.Length,done=fi,total=resolved.Length});}
   rows.Add(new{index,candidates=best.Select(v=>new{name=v.Item1,similarity=v.Item2,preview=Png(v.Item3)}).ToArray(),compared,original=Png(target),warning=best.Count>0&&best[0].Item2>=.7?"候选按字形相似度排序，仍需核对原字体。":"相似度偏低，可能缺少字体或原稿有变形；请人工比较。"});
  }}return new{type="result",ok=true,rows,requestedFonts=requested.Length,resolvedFonts=resolved.Length};}
 }
}
